d=s['diagnostic_cpu_elapsed'];lines += ['',f"The separate CPU-counter diagnostic elapsed was {d['before']['median_seconds']*1000:.6f} → {d['after']['median_seconds']*1000:.6f} ms ({d['change_percent']:+.6f}%). Those observations are excluded from primary elapsed. Other observed median increases:",'','```json',json.dumps(s['contrary_counter_directions'],indent=2),'```','', '## Actual binary and profiles','', '| Metric | Baseline | Candidate |','|---|---:|---:|']
