lines += ['','Fresh compressor Object/image/metadata remain byte-identical. The changed host adapter and shared turn-planner functions are disassembled separately in `host-assembly/`; `host-assembly-comparison.json` records actual static function sizes/call edges. Static instruction counts and CPU sample weights are not dynamic instruction attribution. Whole-call retired instructions are measured independently.','',s['baseline_provenance']['source_note'],'',s['baseline_provenance']['binary_note'],'','Fresh CPU-time samples:','', '| Executable | Exclusive sample weights | Frame-action ancestry | Thread-local ancestry | Tail-cleanup ancestry |','|---|---:|---:|---:|---:|']
for label in ['baseline','candidate','reference']:
 q=s['profiles']['profiles'][label];u=q['ancestry_unions'];lines.append(f"| {label} | {q['total_exclusive_weights']:,} | {u['frame actions']['percent']:.2f}% | {u['thread-local lookup']['percent']:.2f}% | {u['tail cleanup']['percent']:.2f}% |")
lines+=['','These ancestry groups overlap. Samples include the diagnostic harness and are excluded from primary elapsed. They do not partition retired instructions. The complete top leaves and overlapping categories remain in `profile-numbers.json`.','', '## Qualification and scope','',f"Status: **{s['validation']['status']}**; {len(s['validation']['checks'])} required receipt checks. Counts below are actual executions; inventory rows remain in the JSON. Batches overlap.",'', '| Receipt | Expected | Observed | Exit / expected | Passed |','|---|---:|---:|---:|---|']
for row in s['validation']['checks']:
 if row.get('inventory_only'):continue
